describe("doctests of sympy.printing.str", () => {
  it("sstr(Eq(a + b, 0))", () => {
    const [a, b] = symbols('a b');
    const unicode = pprintUseUnicode(false);
    try {
      expect(text(sstr(Relational(add(a, b), rational(0), '==', { evaluate: false }), {}))).toBe('Eq(a + b, 0)');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
});

